/*
 * Quizzy moderator screens: small additions to the design's quizzy.css.
 * Keep the design stylesheet untouched; put app-specific rules here.
 */

fieldset.option-fieldset { border: 0; margin: 0 0 20px; padding: 0; min-width: 0; }
fieldset.option-fieldset legend { padding: 0; margin-bottom: 6px; }
.option-fieldset__actions { margin-top: 14px; margin-bottom: 28px; }

.option-row { grid-template-columns: minmax(0, 1fr) auto auto; }
.option-row__text { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.option-row__label { font-weight: 600; font-size: 15px; }
.option-row__correct { font-size: 15px; white-space: nowrap; }

.activation-form { margin: 0; }
.question-item__actions form { margin: 0; }
.question-item__actions .checkbox { font-size: 15px; }

.quiz-item .buttons { justify-content: flex-start; }

.danger-zone {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 2px dashed var(--c-pink);
}
.danger-zone h2 { font-size: clamp(22px, 2.6vw, 30px); margin-bottom: 8px; }
.danger-zone .field-hint { margin-bottom: 16px; }

.preview-actions { margin-top: 24px; }
.play-options form { margin: 0; }

/* Phones: stack the option row and the question card. */
@media (max-width: 700px) {
  .option-row { grid-template-columns: minmax(0, 1fr) auto; }
  .option-row > button { grid-column: 2; grid-row: 1; }
  .option-row__correct { grid-column: 1 / -1; grid-row: 2; white-space: normal; }
  .question-item { grid-template-columns: auto 1fr; }
  .question-item__actions { grid-column: 1 / -1; align-items: flex-start; }
  .question-item__actions .buttons { justify-content: flex-start; }
